const items = $input.all()

return {
  response: items.map(item => item.json),
}

const body = $input.first().json.body ?? {};

const {
  nome,
  email,
  telefone,
} = body;

const erros = [];

if (nome === undefined || nome === null || nome === '') {
  erros.push('nome é obrigatório');
} else if (typeof nome !== 'string') {
  erros.push('nome deve ser um texto');
} else if (nome.trim().length < 2) {
  erros.push('nome deve ter pelo menos 2 caracteres');
}

if (email === undefined || email === null || email === '') {
  erros.push('email é obrigatório');
} else if (typeof email !== 'string') {
  erros.push('email deve ser um texto');
} else if (
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())
) {
  erros.push('email inválido');
}

if (
  telefone === undefined ||
  telefone === null ||
  telefone === ''
) {
  erros.push('telefone é obrigatório');
} else if (typeof telefone !== 'string') {
  erros.push('telefone deve ser um texto');
} else {
  const telefoneNormalizado = telefone.trim();

  if (
    !/^\([1-9]{2}\) (?:[2-8][0-9]{3}|9[0-9]{4})-[0-9]{4}$/.test(
      telefoneNormalizado,
    )
  ) {
    erros.push(
      'telefone inválido; use o formato (DD) 99999-9999 ou (DD) 9999-9999',
    );
  }
}

return {
  nome: typeof nome === 'string' ? nome.trim() : nome,
  email: typeof email === 'string' ? email.trim() : email,
  telefone:
    typeof telefone === 'string' ? telefone.trim() : telefone,

  erros,
  valido: erros.length === 0,

  trace_id: $execution.id,
  started_at: Date.now(),
};

